algorithm.rustSketch:
use std::cmp::Reverse;
use std::collections::BinaryHeap;
fn smallest(values: &[i32]) -> Option<i32> {
    let mut heap = BinaryHeap::new();
    for &value in values { heap.push(Reverse(value)); }
    heap.pop().map(|Reverse(value)| value)
}

